obs=s.reset();base=2*(d.qpos[7:26].copy()-lo)/(hi-lo)-1;ix=[18,19,20,21];site=m.site('left_hand').id

def bal(obs):
 quat=obs[3:7];p=np.arctan2(2*(quat[0]*quat[2]-quat[3]*quat[1]),1-2*(quat[1]**2+quat[2]**2));r=obs[32];a=base.copy();z=p+2*r
