 print('  state x,z',np.round(d.xpos[m.body('pelvis').id][[0,2]],3),'hand',np.round(d.site_xpos[site],3),'angles',np.round(d.qpos[-2:],3),'contacts',contacts(),'done',done)
 if done:break
